-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- PHILEMON - HIN Combined
-- Generated: 2026-01-20T22:32:22.381Z

-- c001-v001: Paulos bandi Khristos–ka Yeshu aur Timotheos –ho bhai Philemon-ko –ko priye aur saha-karmi hamare
-- c001-v002: aur Apphia –ko bahan aur Arkhippos –ko saha-sainik hamare aur –ko ke-anusaar ghar tere kalisia
-- c001-v003: anugrah tumhein aur shanti se Parameshwar Pita hamare aur Prabhu Yeshu Khristos
-- c001-v004: Main-dhanyavaad-deta-hoon –ko Parameshwar mere sada smaran tera karta-hua par –ke prarthnaon meri
-- c001-v005: sunkar tera –ko prem aur –ko vishwas jo tu-rakhta-hai ke-prati –ke Prabhu Yeshu aur mein sab –ko pavitron
-- c001-v006: ki –ho sahabhagita –ke vishwas tere kaaragar ho-jaye mein gyaan har achhe –ke mein hum-mein ke-liye Khristos
-- c001-v007: anand kyonki bahut mujhe-mila aur shanti par –ke prem tere ki –ho daya –ke pavitron vistrit-hui-hai ke-dwara tere bhai
-- c001-v008: Isliye bahut mein Khristos sahas rakhte-hue aadesh-dene-ke-liye tujhe –ko uchit
-- c001-v009: ke-dwara –ke prem balki main-vinati-karta-hoon aisa hote-hue jaisa Paulos vridh ab par aur bandi Khristos Yeshu
-- c001-v010: main-vinati-karta-hoon tujh-se ke-liye –ke mere bacche jise maine-janm-diya mein –mein bandhon Onesimos
-- c001-v011: –ko pahle tujhe bekaar ab par bhi tujhe aur mujhe upyogi
-- c001-v012: jise maine-vaapas-bheja tujhe use yeh hai –ho mera dil
-- c001-v013: jise main main-chahta-tha ke-pas apne rakhna ki ke-liye tere meri voh-seva-kare mein –mein bandhon –ke susmachar
-- c001-v014: bina par –ke teri sammati kuchh main-nahin-chahta-tha karna ki na jaisa ke-anusaar majburee –ho bhala tera ho parantu ke-anusaar apni-ichchha
-- c001-v015: shayad kyonki ke-liye is voh-alag-hua ke-liye ghaDi ki sada-ke-liye use tu-paaye
-- c001-v016: ab-nahin jaisa das parantu se-badhkar das bhai priya khaaskar mujhe kitna par adhik tujhe bhi mein shareer aur mein Prabhu
-- c001-v017: yadi isliye mujhe tu-maanta-hai sathi svikaar-kar use jaisa mujhe
-- c001-v018: yadi par kuchh usne-anyay-kiya tujhe ya voh-denadaar-hai yeh mere daal
-- c001-v019: main Paulos maine-likha –se apne haath main main-bhugtan-karoonga ki na main-kahoon tujhe ki bhi tujh-ko-hi mujhe tu-denadaar-hai
-- c001-v020: haan bhai main tujh-se laabh-paauun mein Prabhu taazaa-kar mera –ko dil mein Khristos
-- c001-v021: Bharosa-karke –ke aagya-paalan tere maine-likha tujhe jaante-hue ki bhi se-adhik jo main-kahta-hoon tu-karega
-- c001-v022: sath-hi par bhi taiyaar-kar mere-liye atithi-griha main-asha-karta-hoon kyonki ki ke-dwara –ke prarthnaon tumhare main-diya-jaauunga tumhein
-- c001-v023: Abhivaadan-karta-hai tujhe Epaphras –ho saha-bandi mera mein Khristos Yeshu
-- c001-v024: Markos Aristarkhos Demas Loukas –ho saha-karmi mere
-- c001-v025: –Ho anugrah –ka Prabhu Yeshu Khristos ke-sath –ke atma tumhare Amen

